@Override
	public Map<IBlockState, ModelResourceLocation> putStateModelLocations(Block block) {
		if (block instanceof BlockFruitPod) {
			BlockFruitPod blockFruitPod = (BlockFruitPod) block;
			IAlleleFruit fruit = blockFruitPod.getFruit();
			String modID = fruit.getModID();
			if (modID == null) {
				modID = Constants.MOD_ID;
			}
			String modelName = fruit.getModelName();
			String resourcePath = modID + ":pods/" + modelName;
			for (IBlockState state : block.getBlockState().getValidStates()) {
				String propertyString = getPropertyString(state.getProperties());
				mapStateModelLocations.put(state, new ModelResourceLocation(resourcePath, propertyString));
			}
		}
		return mapStateModelLocations;
	}

@Override
	public Map<IBlockState, ModelResourceLocation> putStateModelLocations(Block block) {
		for (IAllele allele : AlleleManager.alleleRegistry.getRegisteredAlleles().values()) {
			if (allele instanceof IAlleleTreeSpecies) {
				IAlleleTreeSpecies tree = (IAlleleTreeSpecies) allele;
				IBlockState state = block.getDefaultState().withProperty(BlockSapling.TREE, tree);
				LinkedHashMap<IProperty<?>, Comparable<?>> linkedhashmap = Maps.newLinkedHashMap(state.getProperties());
				String modID = tree.getModID();
				String s = String.format("%s:%s", modID, "germlings");
				mapStateModelLocations.put(state, new ModelResourceLocation(s, getPropertyString(linkedhashmap)));
			}
		}
		return mapStateModelLocations;
	}

