		if (individual instanceof ITree) {
			ITree tree = getTree();
			return tree != null &&
					tree.getMate() == null &&
					(ModuleApiculture.doSelfPollination || !tree.isGeneticEqual(individual));
		}
		return false;
	}

@Override
	public void mateWith(IIndividual individual) {
		if (individual instanceof ITree) {
			ITree tree = getTree();
			if (tree == null || world == null) {
				return;
			}

			tree.mate((ITree) individual);
			if (!world.isRemote) {
				sendNetworkUpdate();
			}
		}
	}

