@Override
	protected void actionPerformed(GuiButton button) {
		if (button instanceof GuiButtonPage) {
			GuiButtonPage pageButton = (GuiButtonPage) button;
			if (pageButton.left) {
				entryIndex--;
			} else {
				entryIndex++;
			}
			initGui();
		} else if (button instanceof GuiButtonBack) {
			displayCategories();
