	}

private void setPages(int index) {
		leftPage.clear();
		rightPage.clear();
		if (index < 0 || index >= pages.size()) {
			pageIndex = 0;
			return;
		}
		leftPage.add(pages.get(index));
		if (pages.size() > index + 1) {
			rightPage.add(pages.get(index + 1));
		}
		pageIndex = index;
	}

public void switchPage(int page) {
		if (page % 2 == 1) {
			page -= 1;
		}
		this.nextPage = page;
	}

