private double getComparingCode() {
			IClimateState target = transformer.getTarget();
			IClimateState state = climate.climateState;
			double temp = target.getTemperature() - state.getTemperature();
			double hem = target.getHumidity() - state.getHumidity();
			return Math.abs(temp + hem);
		}

public SpeciesSelectionElement(int xPos, int yPos, IClimateTransformer transformer) {
		super(xPos, yPos, 22, 22);
		addSelfEventHandler(GuiEvent.DownEvent.class, event -> {
			EntityPlayer player = Minecraft.getMinecraft().player;
			ItemStack itemstack = player.inventory.getItemStack();
			if (itemstack.isEmpty()) {
				return;
			}
			IIndividual individual = AlleleManager.alleleRegistry.getIndividual(itemstack);
			if (individual == null) {
				return;
			}
			IAlleleSpecies primary = individual.getGenome().getPrimary();
			EnumTemperature temperature = primary.getTemperature();
			EnumHumidity humidity = primary.getHumidity();
			float temp;
			float humid;
			switch (temperature) {
				case HELLISH:
					temp = 2.0F;
					break;
				case HOT:
					temp = 1.25F;
					break;
				case WARM:
					temp = 0.9F;
					break;
				case COLD:
					temp = 0.15F;
					break;
				case ICY:
					temp = 0.0F;
					break;
				case NORMAL:
				default:
					temp = 0.79F;
					break;
			}
			switch (humidity) {
				case DAMP:
					humid = 0.9F;
					break;
				case ARID:
					humid = 0.2F;
					break;
				case NORMAL:
				default:
					humid = 0.4F;
					break;
			}
			transformer.setTarget(ClimateStateHelper.INSTANCE.create(temp, humid));
		});
	}

