@Override
	public final boolean setCondition(boolean condition, IErrorState errorState) {
		if (errorState == null) {
			return false;
		}
		if (condition) {
			errorStates.add(errorState);
		} else {
			errorStates.remove(errorState);
		}
		return condition;
	}

@Override
	public final boolean contains(IErrorState state) {
		return errorStates.contains(state);
	}

@Override
	public final boolean hasErrors() {
		return !errorStates.isEmpty();
	}

@Override
	public final ImmutableSet<IErrorState> getErrorStates() {
		return ImmutableSet.copyOf(errorStates);
	}

@Override
	public void clearErrors() {
		errorStates.clear();
	}

@Override
	public void writeData(PacketBuffer data) {
		data.writeShort(errorStates.size());
		for (IErrorState errorState : errorStates) {
			data.writeShort(errorState.getID());
		}
	}

@Override
	public void readData(PacketBuffer data) {
		clearErrors();

		short errorStateCount = data.readShort();
		for (int i = 0; i < errorStateCount; i++) {
			short errorStateId = data.readShort();
			IErrorState errorState = ForestryAPI.errorStateRegistry.getErrorState(errorStateId);
			if (errorState != null) {
				errorStates.add(errorState);
			}
		}
	}

@Override
	public void registerErrorState(IErrorState state) {
		if (states.containsKey(state.getID())) {
			throw new RuntimeException("Forestry Error State does not possess a unique id.");
		}

		states.put(state.getID(), state);
		addStateName(state, state.getUniqueName());
	}

@Override
	public void addAlias(IErrorState state, String name) {
		if (!states.values().contains(state)) {
			throw new RuntimeException("Forestry Error State did not exist while trying to register alias.");
		}

		addStateName(state, name);
	}

private static void addStateName(IErrorState state, String name) {
		if (!name.contains(":")) {
			throw new RuntimeException("Forestry Error State name must be in the format <modid>:<name>.");
		}

		if (stateNames.containsKey(name)) {
			throw new RuntimeException("Forestry Error State does not possess a unique name.");
		}

		stateNames.put(name, state);
	}

@Override
	public IErrorState getErrorState(short id) {
		return states.get(id);
	}

