public static EnumMutateChance rateChance(float percent) {

		if (percent >= 20) {
			return HIGHEST;
		} else if (percent >= 15) {
			return HIGHER;
		} else if (percent >= 12) {
			return HIGH;
		} else if (percent >= 10) {
			return NORMAL;
		} else if (percent >= 5) {
			return LOW;
		} else {
			return LOWEST;
		}

	}

