		return visibleOptions.keySet();
	}

public void setOptions(Collection<V> options) {
		clear();
		allOptions.clear();
		for (V option : options) {
			IGuiElement element = optionFactory.apply(option, this);
			allOptions.put(option, element);
		}
		updateVisibleOptions();
	}

