@SuppressWarnings("OptionalUsedAsFieldOrParameterType")
	@Override
	public void write(PacketBuffer buf, Optional<GameProfile> value) {
		if (!value.isPresent()) {
			buf.writeBoolean(false);
		} else {
			buf.writeBoolean(true);
			GameProfile gameProfile = value.get();
			buf.writeUniqueId(gameProfile.getId());
			buf.writeString(gameProfile.getName());
		}
	}

@Override
	public Optional<GameProfile> read(PacketBuffer buf) {
		if (buf.readBoolean()) {
			UUID uuid = buf.readUniqueId();
			String name = buf.readString(1024);
			GameProfile gameProfile = new GameProfile(uuid, name);
			return Optional.of(gameProfile);
		} else {
			return Optional.empty();
		}
	}

@Override
	public DataParameter<Optional<GameProfile>> createKey(int id) {
		return new DataParameter<>(id, this);
	}

@Override
	public Optional<GameProfile> copyValue(Optional<GameProfile> value) {
		return value;
	}

@Override
	@Nullable
	public GameProfile getOwner() {
		return owner;
	}

@Override
	public void setOwner(GameProfile owner) {
		this.owner = owner;
	}

@Override
	public void writeData(PacketBufferForestry data) {
		if (owner == null) {
			data.writeBoolean(false);
		} else {
			data.writeBoolean(true);
			data.writeLong(owner.getId().getMostSignificantBits());
			data.writeLong(owner.getId().getLeastSignificantBits());
			data.writeString(owner.getName());
		}
	}

@Override
	public void readData(PacketBufferForestry data) {
		if (data.readBoolean()) {
			GameProfile owner = new GameProfile(new UUID(data.readLong(), data.readLong()), data.readString());
			setOwner(owner);
		}
	}

@Override
	public void readFromNBT(NBTTagCompound data) {
		if (data.hasKey("owner")) {
			GameProfile owner = PlayerUtil.readGameProfileFromNBT(data.getCompoundTag("owner"));
			if (owner != null) {
				setOwner(owner);
			}
		}
	}

@Override
	public NBTTagCompound writeToNBT(NBTTagCompound data) {
		if (this.owner != null) {
			NBTTagCompound nbt = new NBTTagCompound();
			PlayerUtil.writeGameProfile(nbt, owner);
			data.setTag("owner", nbt);
		}
		return data;
	}

