		RenderManager rendermanager = Minecraft.getMinecraft().getRenderManager();

		rendermanager.renderEntity(dummyItem, 0.0D, 0.0D, 0.0D, 0.0F, 0.0F, false);
		GlStateManager.popMatrix();

