public String getText(EscritoireGame escritoireGame) {
		Notes noteLevel = getNoteLevel(escritoireGame);
		if (lastNoteLevel != noteLevel || researchNote == null) {
			researchNote = getRandomNote(noteLevel);
			lastNoteLevel = noteLevel;
		}

		return researchNote;
	}

private static String getRandomNote(Notes level) {
		List<String> candidates = researchNotes.get(level);
		int index = random.nextInt(candidates.size());
		return candidates.get(index);
	}

public static Notes getNoteLevel(EscritoireGame game) {
		EscritoireGame.Status status = game.getStatus();
		switch (status) {
			case PLAYING: {
				int bounty = game.getBountyLevel();
				if (bounty >= EscritoireGame.BOUNTY_MAX) {
					return Notes.level1;
				} else if (bounty > EscritoireGame.BOUNTY_MAX / 2) {
					return Notes.level2;
				} else if (bounty > EscritoireGame.BOUNTY_MAX / 4) {
					return Notes.level3;
				} else {
					return Notes.level4;
				}
			}
			case FAILURE:
				return Notes.failure;
			case SUCCESS:
				return Notes.success;
			case EMPTY:
				return Notes.empty;
		}
		return null;
	}

public static TemperatureState getState(double heat, double maxHeat) {
		final double scaledHeat = heat / maxHeat;

		if (scaledHeat < 0.20) {
			return TemperatureState.COOL;
		} else if (scaledHeat < 0.45) {
			return TemperatureState.WARMED_UP;
		} else if (scaledHeat < 0.65) {
			return TemperatureState.OPERATING_TEMPERATURE;
		} else if (scaledHeat < 0.85) {
			return TemperatureState.RUNNING_HOT;
		} else if (scaledHeat < 1.0) {
			return TemperatureState.OVERHEATING;
		} else {
			return TemperatureState.MELTING;
		}
	}

