			return ItemStackUtil.isCraftingEquivalent(b2, a);
		}
		if (b instanceof Item) {
			return a.getItem() == b;
		}
		if (b instanceof String) {
			for (ItemStack stack : OreDictionary.getOres((String) b)) {
				if (areEqual(a, stack)) {
					return true;
				}
			}
		}
		return false;
