public RevolvingList(Collection<? extends T> collection) {
		Preconditions.checkArgument(!collection.isEmpty());
		for (T object : collection) {
			Preconditions.checkNotNull(object);
			list.add(object);
		}
	}

public void rotateLeft() {
		list.addFirst(list.removeLast());
	}

public void rotateRight() {
		list.addLast(list.removeFirst());
	}

public T getCurrent() {
		return list.getFirst();
	}

public void setCurrent(T e) {
		if (!list.contains(e)) {
			return;
		}

		while (!getCurrent().equals(e)) {
			rotateRight();
		}
	}

@Override
	public final T put(P key, T value) {
		Preconditions.checkArgument(isValidKey(key), "Key is invalid");
		Preconditions.checkNotNull(value);
		return super.put(key, value);
	}

@Override
	public final boolean containsKey(Object key) {
		P stack = getStack(key);
		if (stack == null) {
			return false;
		}
		for (Map.Entry<P, T> entry : this.entrySet()) {
			if (areEqual(stack, entry.getKey())) {
				return true;
			}
		}
		return super.containsKey(key);
	}

@Override
	@Nullable
	public final T get(Object key) {
		P stack = getStack(key);
		if (stack == null) {
			return null;
		}
		for (Map.Entry<P, T> entry : this.entrySet()) {
			if (areEqual(stack, entry.getKey())) {
				return entry.getValue();
			}
		}
		return super.get(key);
	}

