public int getStoredFertilizerScaled(IFarmInventoryInternal inventory, int scale) {
		if (storedFertilizer == 0) {
			return 0;
		}

		return storedFertilizer * scale / (inventory.getFertilizerValue() + BUFFER_FERTILIZER);
	}

