		super("lowSoil." + threshold, "lowSoil", "low_soil");
		this.threshold = threshold;
	}

@Override
	public String getDescription() {
		return super.getDescription() + " < " + threshold;
	}

@Override
	public int maxParameters() {
		return 1;
