protected AIButterflyBase(EntityButterfly entity) {
		this.entity = entity;
	}

@Nullable
	protected Vec3d getRandomDestination() {
		if (entity.isInWater()) {
			return getRandomDestinationUpwards();
		}

		Vec3d entityPos = new Vec3d(entity.posX, entity.posY, entity.posZ);
		Vec3d randomTarget = RandomPositionGenerator.findRandomTargetBlockAwayFrom(entity, 16, 7, entityPos);

		if (randomTarget != null && validateDestination(randomTarget, false)) {
			return randomTarget;
		}
		return null;
	}

@Nullable
	protected Vec3d getRandomDestinationUpwards() {
		Vec3d destination = new Vec3d(entity.posX, entity.posY + entity.getRNG().nextInt(10) + 2, entity.posZ);
		if (validateDestination(destination, true)) {
			return destination;
		} else {
			return null;
		}
	}

private boolean validateDestination(Vec3d dest, boolean allowFluids) {
		if (dest.y < 1) {
			return false;
		}
		BlockPos pos = new BlockPos(dest);
		if (!entity.world.isBlockLoaded(pos)) {
			return false;
		}
		IBlockState blockState = entity.world.getBlockState(pos);
		Block block = blockState.getBlock();
		if (!allowFluids && blockState.getMaterial().isLiquid()) {
			return false;
		}
		if (!block.isPassable(entity.world, pos)) {
			return false;
		}
		return entity.getButterfly().isAcceptedEnvironment(entity.world, dest.x, dest.y, dest.z);
	}

public AIButterflyFlee(EntityButterfly entity) {
		super(entity);
		setMutexBits(3);
	}

@Override
	public boolean shouldExecute() {

		EntityPlayer player = entity.world.getClosestPlayerToEntity(entity, entity.getButterfly().getGenome().getPrimary().getFlightDistance());

		if (player == null || player.isSneaking()) {
			return false;
		}

		if (!entity.getEntitySenses().canSee(player)) {
			return false;
		}

		flightTarget = getRandomDestination();
		if (flightTarget == null) {
			return false;
		}

		if (player.getDistanceSq(flightTarget.x, flightTarget.y, flightTarget.z) < player.getDistance(entity)) {
			return false;
		}

		entity.setDestination(flightTarget);
		entity.setState(EnumButterflyState.FLYING);
		return true;
	}

protected AIButterflyInteract(EntityButterfly entity) {
		super(entity);
		setMutexBits(3);
	}

@Override
	public boolean shouldExecute() {
		if (entity.getState() != EnumButterflyState.RESTING) {
			return false;
		}

		rest = new BlockPos((int) entity.posX, (int) Math.floor(entity.posY) - 1, (int) entity.posZ);
		if (entity.world.isAirBlock(rest)) {
			return false;
		}

		canInteract = canInteract();

		return canInteract;
	}

@Override
	public boolean shouldContinueExecuting() {
		return canInteract && !hasInteracted;
	}

@Override
	public void startExecuting() {
	}

@Override
	public void resetTask() {
		canInteract = false;
		hasInteracted = false;
		rest = null;
	}

protected void setHasInteracted() {
		hasInteracted = true;
	}

public AIButterflyMate(EntityButterfly entity) {
		super(entity);
	}

@Override
	protected boolean canInteract() {
		if (entity.getButterfly().getMate() == null && entity.canMate()) {
			return true;
		}
		if (entity.cooldownEgg > 0) {
			return false;
		}

		if (entity.getButterfly().getMate() == null) {
			return false;
		}

		if (entity.world.countEntities(EntityButterfly.class) > ModuleLepidopterology.spawnConstraint) {
			return false;
		}

		return rest != null && GeneticsUtil.canNurse(entity.getButterfly(), entity.world, rest);
	}

@Override
	public void updateTask() {
		if (shouldContinueExecuting()) {
			if (entity.getButterfly().getMate() == null && targetMate != null) {
				if (entity.cooldownMate <= 0 && entity.getDistance(targetMate) < 9.0D) {
					entity.getButterfly().mate(targetMate.getButterfly());
					targetMate.getButterfly().mate(entity.getButterfly());
					entity.cooldownMate = EntityButterfly.COOLDOWNS;
				}
			} else if (rest != null) {
				IButterflyNursery nursery = GeneticsUtil.getOrCreateNursery(null, entity.world, rest, false);
				if (nursery != null) {
					if (nursery.canNurse(entity.getButterfly())) {
						nursery.setCaterpillar(entity.getButterfly().spawnCaterpillar(entity.world, nursery));
						//Log.finest("A butterfly '%s' laid an egg at %s/%s/%s.", entity.getButterfly().getIdent(), rest.posX, rest.posY, rest.posZ);
						if (entity.getRNG().nextFloat() < 1.0f / entity.getButterfly().getGenome().getFertility()) {
							entity.setHealth(0);
						}
					}
				}
				setHasInteracted();
				entity.cooldownEgg = EntityButterfly.COOLDOWNS;
			}
		}
	}

@Override
	public boolean shouldExecute() {
		if (!super.shouldExecute()) {
			return false;
		}
		if (entity.getButterfly().getMate() == null) {
			if (!entity.canMate()) {
				return false;
			} else {
				targetMate = getNearbyMate();
				return targetMate != null;
			}
		}
		return true;
	}

@Override
	public boolean shouldContinueExecuting() {
		if (!super.shouldContinueExecuting()) {
			return false;
		}
		if (entity.getButterfly().getMate() == null) {
			return targetMate != null && targetMate.isEntityAlive() && targetMate.canMate();
		}
		return true;
	}

@Override
	public void resetTask() {
		super.resetTask();

		targetMate = null;
	}

@Nullable
	private EntityButterfly getNearbyMate() {
		float f = 8.0F;
		List<EntityButterfly> nextButterflys = entity.world.getEntitiesWithinAABB(EntityButterfly.class, this.entity.getEntityBoundingBox().expand(f, f, f));
		double d0 = Double.MAX_VALUE;
		EntityButterfly nextButterfly = null;

		for (EntityButterfly butterfly : nextButterflys) {
			if (this.entity.canMateWith(butterfly) && this.entity.getDistance(butterfly) < d0) {
				nextButterfly = butterfly;
				d0 = this.entity.getDistance(butterfly);
			}
		}

		return nextButterfly;
	}

protected AIButterflyMovement(EntityButterfly entity) {
		super(entity);
	}

@Override
	public boolean shouldContinueExecuting() {
		if (entity.getState() != EnumButterflyState.FLYING) {
			return false;
		}
		if (flightTarget == null) {
			return false;
		}
		// Abort if the flight target changed on us.
		if (entity.getDestination() == null || !entity.getDestination().equals(flightTarget)) {
			return false;
		}

		// Continue if we have not yet reached the destination.
		if (entity.getDestination().squareDistanceTo(entity.getPositionVector()) > 2.0f) {
			return true;
		}

		entity.setDestination(null);
		return false;
	}

@Override
	public void updateTask() {
		// Reset destination if we did collide.
		if (entity.isInWater()) {
			flightTarget = getRandomDestinationUpwards();
		} else if (entity.collided) {
			flightTarget = entity.getRNG().nextBoolean() ? getRandomDestination() : null;
		} else if (entity.world.rand.nextInt(300) == 0) {
			flightTarget = getRandomDestination();
		}
		entity.setDestination(flightTarget);
		entity.changeExhaustion(1);
	}

@Override
	public void startExecuting() {
	}

@Override
	public void resetTask() {
		flightTarget = null;
	}

public AIButterflyPollinate(EntityButterfly entity) {
		super(entity);
	}

@Override
	protected boolean canInteract() {
		if (entity.cooldownPollination > 0 || !ModuleLepidopterology.isPollinationAllowed()) {
			return false;
		}

		if (rest == null) {
			return false;
		}

		ICheckPollinatable checkPollinatable = GeneticsUtil.getCheckPollinatable(entity.world, rest);
		if (checkPollinatable == null) {
			return false;
		}

		if (!entity.getButterfly().getGenome().getFlowerProvider().isAcceptedPollinatable(entity.world, checkPollinatable)) {
			return false;
		}

		return entity.getPollen() == null || checkPollinatable.canMateWith(entity.getPollen());
	}

@Override
	public void updateTask() {
		if (shouldContinueExecuting() && rest != null) {
			ICheckPollinatable checkPollinatable = GeneticsUtil.getCheckPollinatable(entity.world, rest);
			if (checkPollinatable != null) {
				if (entity.getPollen() == null) {
					entity.setPollen(checkPollinatable.getPollen());
					//					Log.finest("A butterfly '%s' grabbed a pollen '%s' at %s/%s/%s.", entity.getButterfly().getIdent(), entity.getPollen().getIdent(), rest.posX, rest.posY, rest.posZ);
				} else if (checkPollinatable.canMateWith(entity.getPollen())) {
					IPollinatable realPollinatable = GeneticsUtil.getOrCreatePollinatable(null, entity.world, rest, false);
					if (realPollinatable != null) {
						realPollinatable.mateWith(entity.getPollen());
						//						Log.finest("A butterfly '%s' unloaded pollen '%s' at %s/%s/%s.", entity.getButterfly().getIdent(), entity.getPollen().getIdent(), rest.posX, rest.posY, rest.posZ);
						entity.setPollen(null);
					}
				}
			}
			setHasInteracted();
			entity.cooldownPollination = EntityButterfly.COOLDOWNS;
		}
	}

public AIButterflyRest(EntityButterfly entity) {
		super(entity);
		setMutexBits(3);
	}

@Override
	public boolean shouldExecute() {

		if (entity.getExhaustion() < EntityButterfly.EXHAUSTION_REST
			&& entity.canFly()) {
			return false;
		}

		int x = (int) entity.posX;
		int y = (int) Math.floor(entity.posY);
		int z = (int) entity.posZ;
		BlockPos pos = new BlockPos(x, y, z);

		if (!canLand(pos)) {
			return false;
		}

		pos = pos.add(x, -1, z);
		if (entity.world.isAirBlock(pos)) {
			return false;
		}
		IBlockState blockState = entity.world.getBlockState(pos);
		if (blockState.getMaterial().isLiquid()) {
			return false;
		}
		if (!entity.getButterfly().isAcceptedEnvironment(entity.world, x, pos.getY(), z)) {
			return false;
		}

		entity.setDestination(null);
		entity.setState(EnumButterflyState.RESTING);
		return true;
	}

@Override
	public boolean shouldContinueExecuting() {
