private boolean canLand(BlockPos pos) {
		if (!entity.world.isBlockLoaded(pos)) {
			return false;
		}
		IBlockState blockState = entity.world.getBlockState(pos);
		Block block = blockState.getBlock();
		if (!block.isPassable(entity.world, pos)) {
			return false;
		}
		if (isPlant(blockState)) {
			return true;
		}

		IBlockState blockStateBelow = entity.world.getBlockState(pos.down());
		Block blockBelow = blockStateBelow.getBlock();
		return isRest(blockBelow) || blockBelow.isLeaves(blockStateBelow, entity.world, pos.down());
	}

private static boolean isRest(Block block) {
		if (block instanceof BlockFence) {
			return true;
		}
		return block instanceof BlockWall;
	}

private static boolean isPlant(IBlockState blockState) {
		Block block = blockState.getBlock();
		if (block instanceof BlockFlower) {
			return true;
		} else if (block instanceof IPlantable) {
			return true;
		} else if (block instanceof IGrowable) {
			return true;
		} else {
			return blockState.getMaterial() == Material.PLANTS;
		}
	}

public AIButterflyRise(EntityButterfly entity) {
		super(entity);
		setMutexBits(1);
	}

@Override
	public boolean shouldExecute() {
		if (entity.getDestination() != null) {
			return false;
		}

		if (!entity.collidedHorizontally && entity.getRNG().nextInt(64) != 0) {
			return false;
		}

		flightTarget = getRandomDestinationUpwards();
		if (flightTarget == null) {
			if (entity.getState().doesMovement) {
				entity.setState(EnumButterflyState.HOVER);
			}
			return false;
		}

		entity.setDestination(flightTarget);
		entity.setState(EnumButterflyState.RISING);
		return true;
	}

@Override
	public boolean shouldContinueExecuting() {
		if (entity.getState() != EnumButterflyState.RISING) {
			return false;
		}
		if (flightTarget == null) {
			return false;
		}
		// Abort if the flight target changed on us.
		if (entity.getDestination() == null || !entity.getDestination().equals(flightTarget)) {
			return false;
		}

		// Continue if we have not yet reached the destination.
		if (entity.getDestination().squareDistanceTo(entity.getPositionVector()) > 2.0f) {
			return true;
		}

		entity.setDestination(null);
		return false;
	}

@Override
	public void updateTask() {
		if (entity.isInWater()) {
			flightTarget = getRandomDestinationUpwards();
		} else if (entity.collidedVertically && entity.getRNG().nextInt(62) == 0) {
			flightTarget = null;
		}

		entity.setDestination(flightTarget);
		entity.changeExhaustion(1);
	}

